const descriptors = new Map(kernelManifest.map(entry => [entry.entry, entry]));

export async function loadKernel(runtime, name, {fetch: fetcher = globalThis.fetch} = {}) {
  const descriptor = typeof name === "string" ? descriptors.get(name) : name;
  if (!descriptor || descriptors.get(descriptor.entry) !== descriptor)
    throw new Error(`Unknown WebGPU compute kernel ${typeof name === "string" ? name : name?.entry}`);
  if (typeof fetcher !== "function") throw new Error("WGSL loading requires fetch");
  const url = new URL(descriptor.file, import.meta.url);
  const response = await fetcher(url);
  if (!response.ok) throw new Error(`Unable to load WGSL ${descriptor.entry}: HTTP ${response.status}`);
  return runtime.kernel({name: descriptor.entry, entryPoint: descriptor.entryPoint,
    metadata: descriptor.metadata, wgsl: await response.text()});
}
